package com.xinghuo.web;

import static org.junit.jupiter.api.Assertions.*;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.FilePayload;
import java.nio.file.Path;
import java.util.Map;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.security.web.csrf.DefaultCsrfToken;
import org.thymeleaf.context.Context;
import org.thymeleaf.spring6.SpringTemplateEngine;
import org.thymeleaf.templateresolver.ClassLoaderTemplateResolver;

/** Real templates and scripts; fixtures never reach a production database or upload store. */
@EnabledIfEnvironmentVariable(named="PLAYWRIGHT_UI_TESTS",matches="1")
class XingweiCatalogMaintenancePlaywrightTest {
    private String template(String name){var resolver=new ClassLoaderTemplateResolver();resolver.setPrefix("templates/");resolver.setSuffix(".html");var engine=new SpringTemplateEngine();engine.setTemplateResolver(resolver);var context=new Context();context.setVariables(Map.of("csrf",new DefaultCsrfToken("X-CSRF-TOKEN","_csrf","test-csrf")));return engine.process(name,context);}
    private Browser chromium(Playwright playwright){var options=new BrowserType.LaunchOptions();String executable=System.getenv("XINGHUO_TEST_CHROMIUM");if(executable!=null&&!executable.isBlank())options.setExecutablePath(Path.of(executable));return playwright.chromium().launch(options);}
    private Page setup(Browser browser,boolean manage){
        Page page=browser.newPage(new Browser.NewPageOptions().setViewportSize(390,844).setTimezoneId("Asia/Shanghai"));
        page.route("**/*",r->{String path=java.net.URI.create(r.request().url()).getPath();if(path.startsWith("/assets/"))r.fulfill(new Route.FulfillOptions().setPath(Path.of("src/main/resources/static"+path)));else if(path.startsWith("/api/site-assets/"))r.fulfill(new Route.FulfillOptions().setContentType("image/svg+xml").setBody("<svg xmlns='http://www.w3.org/2000/svg' width='10' height='10'/>") );else r.fulfill(new Route.FulfillOptions().setContentType("text/html").setBody(template(path.endsWith("/maintenance")?"admin-xingwei-maintenance":path.endsWith("/taxonomy")?"admin-xingwei-taxonomy":path.endsWith("/catalog")?"admin-xingwei-catalog":"admin-xingwei-catalog-details")));});
        page.addInitScript("""
            window.calls=[];window.manage=CAN_MANAGE;window.conflict=false;window.previewDelay=0;
            window.service={id:1,version:7,name:'实际服务',slug:'actual-service',gameCode:'MW4',category:'TASK',shortDesc:'真实说明',durationText:'1天',priceMode:'FIXED',priceFixed:88,status:'AVAILABLE',active:true,hotScore:3,expiresAt:'2030-01-01T00:00:00Z',coverImage:null};
            window.game={code:'MW4',name:'实际游戏',nameEn:'Actual game',active:true,businessStatus:'ACTIVE',platformCodes:['PC'],popularityScore:50,featured:false};
            window.category={id:9,gameCode:'MW4',code:'TASK',name:'实际分类',active:true};window.gameRevision='g7';
            window.order={recordKey:'ORDER-1',businessNo:'XH-ORDER-1',status:'DELIVERED',updatedAt:'2026-10-16T10:00:00Z',allowPublicCase:false,publicSummary:null};
            const response=(body,status=200)=>new Response(JSON.stringify(body),{status,headers:{'Content-Type':'application/json'}});
            window.fetch=async(url,options={})=>{const method=options.method||'GET',headers=Object.fromEntries(new Headers(options.headers||{}));const data=options.body instanceof FormData?{fileName:options.body.get('file')?.name}:options.body?JSON.parse(options.body):null;window.calls.push({url,method,headers,data});
              if(url.endsWith('/images/service'))return response({url:'/api/site-assets/uploaded-cover'});
              if(url.endsWith('/impact')){if(window.previewDelay)await new Promise(resolve=>window.releasePreview=resolve);return response({name:'实际游戏',active:true,visibilitySummary:'停用将隐藏公开服务',impactToken:'actual-impact'});}
              if(url.endsWith('/games/bulk'))return response({message:'完成'});
              if(url.endsWith('/games/MW4/editor'))return response({data:{...window.game,name:'另一页面保存的新名称'},revision:'g8'});
              if(url.endsWith('/games/MW4/profile'))return response({...window.game,...data});
              if(url.endsWith('/access'))return response({allowAll:window.manage,permissionCodes:window.manage?['service:manage']:[],canViewOrders:true,canViewQuotes:true,canPublishCase:window.manage,canDelete:window.manage});
              if(url.includes('/maintenance/orders/ORDER-1/case')){if(data.enabled&&!data.privacyConfirmed)return response({message:'请先确认客户授权'},400);window.order={...window.order,allowPublicCase:data.enabled,publicSummary:data.summary};return response({data:window.order,revision:'o8'});}
              if(url.includes('/maintenance/')&&method==='DELETE')return response({message:'存在支付记录，不能删除订单'},400);
              if(url.includes('/maintenance?'))return response({items:[{data:window.order,revision:'o7'}],total:1,page:0,size:25});
              if(method==='PUT'&&url.endsWith('/services/1')){if(window.conflict)return response({message:'记录已变化，请重新读取核对'},409);window.service={...window.service,...data,version:window.service.version+1};return response({data:window.service,revision:'v'+window.service.version});}
              if(method==='PUT'&&url.endsWith('/games/MW4')){window.game={...window.game,...data};return response({data:window.game,revision:'g8'});}
              if(url.endsWith('/catalog/snapshot'))return response({services:[window.service],games:[window.game],categories:[window.category],platforms:[],counts:{}});
              return response({services:[{data:window.service,revision:'v'+window.service.version}],games:[{data:window.game,revision:window.gameRevision}],categories:[{data:window.category,revision:'c7'}],platforms:[{code:'PC',name:'电脑'},{code:'PS5',name:'PS5'}],canManage:window.manage,restoreAdmin:window.manage});
            };
            """.replace("CAN_MANAGE",String.valueOf(manage)));return page;
    }
    @Test void chromiumCompleteMetadataAndMaintenanceUseCurrentRevisionsAndKeepConflicts(){try(Playwright p=Playwright.create();Browser b=chromium(p)){journey(b);}}
    @Test void webkitCompleteMetadataAndMaintenanceUseCurrentRevisionsAndKeepConflicts(){try(Playwright p=Playwright.create();Browser b=p.webkit().launch()){journey(b);}}
    private void journey(Browser browser){
        Page page=setup(browser,true);page.navigate("http://xinghuo.test/admin/xingwei/catalog-details");page.locator("#catalogDetailsRows button").first().click();assertEquals("2030-01-01T08:00",page.locator("#catalogDetails-expiresAt").inputValue());
        page.locator("#catalogDetails-upload-coverImage").setInputFiles(new FilePayload("cover.png","image/png",new byte[]{1,2,3}));page.getByText("上传服务封面",new Page.GetByTextOptions().setExact(true)).click();page.waitForFunction("()=>document.querySelector('#catalogDetails-coverImage').value==='/api/site-assets/uploaded-cover'&&!document.querySelector('#catalogDetailsFields').disabled");
        page.locator("#catalogDetails-hotScore").fill("9.5");page.locator("#catalogDetails-status").selectOption("BUSY");page.locator("#catalogDetails-reason").fill("维护完整资料");page.locator("#catalogDetailsSave").click();page.waitForFunction("()=>!document.querySelector('#catalogDetailsDialog').open");
        assertEquals(true,page.evaluate("()=>{const c=window.calls.find(c=>c.method==='PUT');return c.headers['if-match']==='\"v7\"'&&c.headers['x-csrf-token']==='test-csrf'&&c.data.coverImage==='/api/site-assets/uploaded-cover'&&c.data.expiresAt==='2030-01-01T00:00:00.000Z'&&c.data.hotScore==='9.5'&&c.data.status==='BUSY'&&c.data.active===true;}"));
        page.waitForFunction("()=>document.querySelector('#catalogDetailsRows').getAttribute('aria-busy')==='false'");page.locator("#catalogDetailsRows button").first().click();page.evaluate("()=>window.conflict=true");page.locator("#catalogDetails-name").fill("冲突后保留草稿");page.locator("#catalogDetails-reason").fill("另一次维护");page.locator("#catalogDetailsSave").click();page.waitForFunction("()=>document.querySelector('#catalogDetailsFormMessage').textContent.includes('记录已变化')");assertEquals("冲突后保留草稿",page.locator("#catalogDetails-name").inputValue());page.locator("#catalogDetailsClose").click();
        page.locator("#catalogDetailsMode").selectOption("games");page.locator("#catalogDetailsRows button").first().click();page.locator("#catalogDetails-platformCodes").selectOption(new String[]{"PC","PS5"});page.locator("#catalogDetails-seoTitle").fill("实际搜索标题");page.locator("#catalogDetails-reason").fill("更新平台和搜索展示");page.locator("#catalogDetailsSave").click();page.waitForFunction("()=>!document.querySelector('#catalogDetailsDialog').open");assertEquals(true,page.evaluate("()=>{const c=window.calls.find(c=>c.url.endsWith('/games/MW4')&&c.method==='PUT');return c.headers['if-match']==='\"g7\"'&&c.data.platformCodes.join(',')==='PC,PS5'&&c.data.seoTitle==='实际搜索标题'&&c.data.active===true;}"));
        page.waitForFunction("()=>document.querySelector('#catalogDetailsRows').getAttribute('aria-busy')==='false'");page.locator("#catalogDetailsRows input[type=checkbox]").check();page.locator("#catalogDetailsBulkVisibility").click();assertTrue(page.locator("#catalogDetailsSave").isDisabled());page.locator("#catalogDetails-active").selectOption("false");page.evaluate("()=>window.previewDelay=300");page.getByText("读取影响预览",new Page.GetByTextOptions().setExact(true)).click();page.waitForFunction("()=>typeof window.releasePreview==='function'");assertTrue(page.locator("#catalogDetailsClose").isDisabled());page.evaluate("()=>window.releasePreview()");page.waitForFunction("()=>!document.querySelector('#catalogDetailsFields').disabled");assertTrue(page.locator("#catalogDetailsSave").isDisabled());page.locator("#catalogDetails-acknowledge").check();page.locator("#catalogDetails-reason").fill("核对全部服务影响后停用");page.locator("#catalogDetailsSave").click();page.waitForFunction("()=>!document.querySelector('#catalogDetailsDialog').open");assertEquals(true,page.evaluate("()=>{const c=window.calls.find(c=>c.url.endsWith('/games/bulk'));return c.data.active===false&&c.data.items[0].impactToken==='actual-impact'&&c.data.items[0].revision==='g7';}"));assertEquals(true,page.evaluate("()=>document.documentElement.scrollWidth<=innerWidth"));
        page.navigate("http://xinghuo.test/admin/xingwei/maintenance");page.getByText("公开案例设置",new Page.GetByTextOptions().setExact(true)).click();page.locator("#maintenance-enabled").check();page.locator("#maintenance-summary").fill("已完成脱敏交付");page.locator("#maintenance-reason").fill("客户授权公开");page.locator("#maintenanceSave").click();page.waitForFunction("()=>document.querySelector('#maintenanceFormMessage').textContent.includes('客户授权')");assertEquals("已完成脱敏交付",page.locator("#maintenance-summary").inputValue());page.locator("#maintenance-privacyConfirmed").check();page.locator("#maintenanceSave").click();page.waitForFunction("()=>!document.querySelector('#maintenanceDialog').open");assertEquals(true,page.evaluate("()=>{const c=window.calls.filter(c=>c.method==='PATCH').at(-1);return c.headers['if-match']==='\"o7\"'&&c.headers['x-csrf-token']==='test-csrf'&&c.data.privacyConfirmed&&c.data.summary==='已完成脱敏交付';}"));
        page.waitForFunction("()=>document.querySelector('#maintenanceRows').getAttribute('aria-busy')==='false'");page.getByText("永久删除",new Page.GetByTextOptions().setExact(true)).click();page.locator("#maintenance-confirmation").fill("XH-ORDER-1");page.locator("#maintenanceSave").click();page.waitForFunction("()=>document.querySelector('#maintenanceFormMessage').textContent.includes('存在支付记录')");assertEquals("XH-ORDER-1",page.locator("#maintenance-confirmation").inputValue());assertEquals(true,page.evaluate("()=>document.documentElement.scrollWidth<=innerWidth"));page.close();
        Page viewer=setup(browser,false);viewer.navigate("http://xinghuo.test/admin/xingwei/catalog-details");viewer.getByText("查看资料",new Page.GetByTextOptions().setExact(true)).click();assertTrue(viewer.locator("#catalogDetails-name").isDisabled());assertTrue(viewer.locator("#catalogDetailsSave").isHidden());assertEquals(0,viewer.locator("input[type=file]").count());viewer.navigate("http://xinghuo.test/admin/xingwei/maintenance");viewer.waitForFunction("()=>document.querySelector('#maintenanceRows').textContent.includes('XH-ORDER-1')");assertEquals(0,viewer.locator("#maintenanceRows button").count());viewer.close();
    }
    @Test void chromiumBasicTaxonomyLoadsMatchingFreshDataAndRevision(){try(Playwright p=Playwright.create();Browser b=chromium(p)){
        Page page=setup(b,true);page.navigate("http://xinghuo.test/admin/xingwei/taxonomy");page.locator("[data-kind='edit-game']").first().click();page.waitForFunction("()=>document.querySelector('#xtaxEditDialog').open");assertEquals("另一页面保存的新名称",page.locator("#xtaxEditName").inputValue());page.locator("#xtaxEditReason").fill("维护名称");page.locator("#xtaxEditSave").click();page.waitForFunction("()=>!document.querySelector('#xtaxEditDialog').open");assertEquals(true,page.evaluate("()=>{const c=window.calls.find(c=>c.url.endsWith('/profile'));return c.headers['if-match']==='\"g8\"'&&c.data.name==='另一页面保存的新名称';}"));
        page.navigate("http://xinghuo.test/admin/xingwei/catalog");page.locator("[data-action='edit']").first().click();page.locator("#xcatEditReason").fill("维护简版价格");page.locator("#xcatEditSave").click();page.waitForFunction("()=>!document.querySelector('#xcatEditDialog').open");assertEquals(true,page.evaluate("()=>window.calls.find(c=>c.method==='PUT'&&c.url.endsWith('/services/1')).headers['if-match']==='\"v7\"'"));
    }}
}
